// Generated from the individually edited RU event-outcomes catalog (E051-E100).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E051_E100 = Object.freeze({"E051.1":{"s":"Охотница принимает яйцо обеими руками и долго осматривает трещины на скорлупе. За то, что вы не стали торговаться, она отсчитывает золото."},"E051.2":{"s":"Вы называете цену выше предложенной, и охотница после тяжёлой паузы соглашается. Монеты переходят к отряду, яйцо остаётся под её защитой.","f":"Охотница замечает, что вы пытаетесь нажиться на кладке, и зовёт сородичей. Разговор обрывается началом стычки."},"E051.3":{"s":"{{heroName}} договаривается с охотницей о сопровождении до безопасной дороги. За помощь она вручает отряду золото и дорожные припасы.","f":"{{heroName}} предлагает охотнице охрану, но та не доверяет чужому отряду. Вы расходитесь без сделки."},"E051.4":{"s":"Пока охотница отвлечена, вы уносите тяжёлое яйцо из кострища. Добыча приносит отряду золото.","f":"Когда вы поднимаете яйцо, охотница издаёт резкий зов, и со склонов отвечают вооружённые дракониды. Начинается битва."},"E052.1":{"s":"Изгнанник опускается на колено и произносит клятву без единой оговорки. Молодой драконид вступает в отряд.","f":"Изгнанник не выдерживает расспросов о прошлом и уходит после совместной трапезы. Припасов становится меньше.","v":{"rs":"Вы готовы принять изгнанника, но свободного места для нового бойца не находится. На прощание драконид оставляет вам немного золота."}},"E052.2":{"s":"Испытательный поединок заканчивается без смертельного удара. Убедившись в вашей решимости, драконид приносит присягу отряду.","f":"Испытание выходит из-под контроля: {{affectedHeroName}} получает тяжёлое ранение. Драконид так и не приносит клятву.","v":{"rs":"Поединок убеждает изгнанника в вашей силе, но присоединиться к отряду он не может. Вместо присяги он передаёт вам золото.","nf":"Поединок прерывается прежде, чем кто-либо из доступных бойцов получает ранение. Присяга так и не принесена."}},"E052.3":{"s":"{{heroName}} честно выдерживает поединок и первым протягивает сопернику руку. Драконид принимает предложенное место в отряде.","f":"Драконид наносит решающий удар, и {{affectedHeroName}} получает тяжёлое ранение. Проверка силы заканчивается без нового союзника.","v":{"rs":"{{heroName}} заслуживает уважение драконида, но места в отряде для него не находится. Изгнанник оставляет золото в знак признания.","nf":"Поединок заканчивается без тяжёлых ранений, однако драконид не принимает предложенную клятву."}},"E052.4":{"s":"Вы отказываете изгнаннику, не требуя от него доказательств. Он коротко кланяется и уходит искать другой отряд."},"E053.1":{"s":"Сборщик пересчитывает шестнадцать золотых монет и отступает от дороги. Проход открыт, хотя в кошельке стало легче."},"E053.2":{"s":"Вместо монет вы отдаёте сборщикам часть провизии. Дракониды принимают плату и пропускают отряд."},"E053.3":{"s":"Вы заставляете сборщиков признать, что право на дань здесь не доказано. Чтобы закрыть спор, они выплачивают отряду золото.","f":"Сборщики отказываются обсуждать свои права и берутся за оружие. Начинается стычка."},"E053.4":{"s":"{{heroName}} замечает ошибку в расчётах сборщиков и требует вернуть лишнее. Дракониды нехотя отдают золото.","f":"Сборщики находят в расчёте {{heroName}} неучтённую пошлину и взыскивают её с отряда. Казна теряет золото."},"E054.1":{"s":"Драконидский дозор платит за ваше молчание и указывает тропу прочь от пещеры. Вы уходите с золотом, не тревожа спящего дракона."},"E054.2":{"s":"Вы требуете двойной платы, и дозорные, поглядывая на вход в пещеру, уступают. Золото оказывается у отряда.","f":"Дозорные считают ваши требования угрозой тайне пещеры и перекрывают выход. Начинается стычка."},"E054.3":{"s":"Вы проскальзываете мимо дозора и забираете из бокового грота золото и оставленные припасы. Древний дракон не просыпается.","f":"Под ногами осыпается камень, и грохот будит обитателей пещеры. Путь к выходу перекрыт — начинается битва."},"E054.4":{"s":"{{heroName}} разбирает защитные знаки и находит проход к спрятанному золоту. Печати остаются нетронутыми.","f":"Один из знаков вспыхивает, когда {{heroName}} пытается его прочесть. {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Защитная печать срабатывает, но среди доступных бойцов никто не получает тяжёлого ранения. Тайник остаётся запечатанным."}},"E055.1":{"s":"За уплаченные монеты зверолюди передают вам две связки дорожной еды. Стороны расходятся, не споря о праве на водопой."},"E055.2":{"s":"Совместная охота проходит без ссор, и зверолюди делятся добычей. Отряд получает припасы.","f":"Охотники не могут поделить право на добычу и обвиняют ваш отряд в обмане. Спор переходит в стычку."},"E055.3":{"s":"{{heroName}} назначает каждой стороне своё время у воды и прекращает спор. Благодарные зверолюди делятся припасами и золотом.","f":"{{heroName}} предлагает расписание, но обе стороны требуют первыми подойти к воде. Договориться не удаётся."},"E055.4":{"s":"Вы занимаете водопой силой, и зверолюди отступают в заросли. Оставленные ими припасы достаются отряду.","f":"Зверолюди не отступают: на зов выходят соседние кланы. Вместо быстрого захвата начинается битва."},"E056.1":{"s":"Вы проходите охотничье испытание, не повредив ни одного трофея. Старейшины зверолюдей вручают вам золото.","f":"Испытание заканчивается неудачным броском: {{affectedHeroName}} получает тяжёлое ранение. Трофеи остаются на дереве.","v":{"nf":"Испытание срывается, но среди доступных бойцов никто не получает тяжёлого ранения. Награды от охотников нет."}},"E056.2":{"s":"{{heroName}} выслеживает самую опасную добычу и возвращается с трофеем. Зверолюди признают успех и платят золотом.","f":"След выводит {{heroName}} прямо к вооружённым охотникам, не желающим уступать добычу. Начинается стычка."},"E056.3":{"s":"Вы успеваете снять с ветвей самые ценные рога и унести их к торговцам. Выручка пополняет казну.","f":"Пока вы срезаете трофеи, возвращаются их хозяева. Зверолюди хватаются за оружие — начинается стычка."},"E056.4":{"s":"Вы оставляете дерево с трофеями нетронутым. Зверолюди провожают отряд настороженными взглядами, но не преследуют."},"E057.1":{"s":"Волчий наёмник пересчитывает плату, проверяет крепление меча и встаёт рядом с вашими бойцами. Договор заключён.","v":{"rs":"Волчий наёмник готов служить, но взять нового бойца не удаётся. Он возвращает предложение и передаёт компенсацию золотом."}},"E057.2":{"s":"После короткого торга зверолюд соглашается на меньшую сумму и убирает меч в ножны. У отряда появляется новый наёмник.","f":"Волчий наёмник отвергает предложенную цену, но плату за торг не возвращает. Отряд уходит без нового бойца.","v":{"rs":"Зверолюд соглашается на цену, но места для него не находится. Вместо вступления в отряд вы получаете золото."}},"E057.3":{"s":"{{heroName}} выдерживает проверочный поединок и не добивает упавшего соперника. Волчий наёмник признаёт отряд достойным и присоединяется к нему.","f":"Волчий наёмник оказывается опытнее: {{affectedHeroName}} получает тяжёлое ранение в поединке. Договор о службе не заключён.","v":{"rs":"{{heroName}} проходит испытание наёмника, но присоединиться к отряду тот не может. Он вручает золото вместо обещанной службы.","nf":"Поединок завершается без тяжёлой раны у доступных бойцов. Наёмник отказывается от договора."}},"E057.4":{"s":"Вы отказываетесь платить за чужую самоуверенность. Волчий наёмник усмехается и идёт искать нового нанимателя."},"E058.1":{"s":"Вы выставляете перед лагерем мешки с провизией. Зверолюди забирают свою долю и исчезают в темноте без боя."},"E058.2":{"s":"Вожак принимает золото и отзывает стаю от ваших костров. Лагерь остаётся цел, казна — легче."},"E058.3":{"s":"Бойцы поднимают такой грохот щитами и котлами, что стая принимает лагерь за многочисленный гарнизон. Зверолюди отступают.","f":"Вожак понимает вашу уловку и отвечает настоящим боевым воем. Стая бросается к лагерю — начинается стычка."},"E058.4":{"s":"{{heroName}} укрепляет подступы к кострам, и стая не решается подойти. После ночной тревоги отряд находит оставленные зверолюдьми припасы.","f":"{{heroName}} не успевает закрыть последний проход в ограждении. Через него прорывается часть стаи — начинается стычка."},"E058.5":{"s":"Вы отдаёте приказ атаковать до того, как стая сомкнёт кольцо. Отряд выходит из лагеря навстречу большой битве."},"E059.1":{"s":"Травница отсчитывает сушёное мясо и свёртки трав, получая условленное золото. Новые припасы отправляются в обоз."},"E059.2":{"s":"Вы находите редкую кость среди старых звериных останков, и травница расплачивается мясом и золотом.","f":"Поиски затягиваются до темноты, а нужной кости нет. Отряд расходует припасы впустую."},"E059.3":{"s":"{{heroName}} указывает травнице место старого захоронения зверя. За точную подсказку она выдаёт отряду припасы.","f":"{{heroName}} не находит надёжных признаков нужной кости. Травница отказывает в награде."},"E059.4":{"s":"Вы отвлекаете травницу разговором и уносите сумку с сушёным мясом. Припасы оказываются в обозе.","f":"Травница замечает руку у своего прилавка и громко зовёт сородичей. Начинается стычка."},"E060.1":{"s":"Следы выводят вас к лагерю, где зверолюди меняют мясо на монеты. Отряд уходит с золотом и припасами.","f":"Вы приходите к лагерю в разгар тревоги, и часовые принимают вас за налётчиков. Начинается стычка."},"E060.2":{"s":"Вы нагоняете обоз и получаете часть его запасов в обмен на помощь с дорогой. Припасы пополняются.","f":"У обоза слишком много вооружённой охраны, и попытка подойти вызывает общую тревогу. Начинается битва."},"E060.3":{"s":"{{heroName}} различает на земле следы носильщиков и колёс, обходя чужие дозоры. Вы находите оставленные золото и припасы.","f":"{{heroName}} ведёт отряд по ложным следам, и к вечеру становится ясно, что обоз ушёл другим путём. Добычи нет."},"E060.4":{"s":"Вы обходите истоптанную долину по сухому склону. Ни чужих складов, ни чужих клинков вам не достаётся."},"E061.1":{"s":"Вы поднимаете крышку сундука, пока свет в ядре стража почти погас. Внутри лежат золотые монеты.","f":"Крышка сдвигается, и каменно-металлический страж мгновенно распрямляется. Он блокирует дорогу, начиная стычку."},"E061.2":{"s":"Получив долю припасов, древний механизм на миг оживает и открывает сундук. В благодарность за запущенное ядро вам достаётся золото."},"E061.3":{"s":"{{heroName}} меняет порядок рун на броне стража, и тот открывает сундук с золотом и складскими припасами.","f":"Механизм принимает команду {{heroName}} за попытку взлома и резко сжимает каменную руку. {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Страж блокирует попытку перенастройки, но среди доступных бойцов никто не получает тяжёлого ранения. Сундук остаётся закрытым."}},"E061.4":{"s":"Вы проходите мимо неподвижного стража, не касаясь сундука. Слабое свечение ядра остаётся за спиной."},"E062.1":{"s":"Вы перекрываете дорогу, и колонна замирает, ожидая нового приказа. В оставленном ею транспортном ящике находятся припасы.","f":"Конструкты воспринимают попытку остановить их как враждебный приказ. Колонна перестраивается для стычки."},"E062.2":{"s":"Следуя за механическим строем, вы находите запертый склад без охраны. Внутри остаётся золото прежних хозяев.","f":"Колонна приводит вас к давно опустошённому складу. Пока вы ищете другой путь, уходят припасы."},"E062.3":{"s":"{{heroName}} читает выцветшую командную руну и указывает, где конструкты оставили груз. Отряд забирает золото и припасы.","f":"{{heroName}} не находит конца древней команды, и колонна продолжает марш. Обещанного склада вы не видите."},"E062.4":{"s":"Вы пропускаете колонну, не задавая вопросов. Последний конструкт повторяет приказ и исчезает за поворотом."},"E063.1":{"s":"Кристаллы отделяются от расколотого корпуса без повреждений. Их стоимость превращается в золото для отряда.","f":"Стоит коснуться кристалла, как повреждённый голем выбрасывает остаточный разряд. {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Голем выпускает остаточный разряд, но среди доступных бойцов нет пострадавшего. Кристаллы остаются в корпусе."}},"E063.2":{"s":"Вы аккуратно вынимаете уцелевшее ядро из разбитой груди голема. За такую находку платят хорошим золотом.","f":"Едва вы освобождаете ядро, соседние конструкты распознают попытку разборки как нападение. Начинается стычка."},"E063.3":{"s":"{{heroName}} закрепляет расколотые плиты и последовательно снимает ценные детали. Разборка приносит золото без новых повреждений.","f":"{{heroName}} находит под бронёй повреждённый замок, который нельзя открыть без разрушения ядра. Безопасная разборка заканчивается без добычи."},"E063.4":{"s":"Вы соединяете обрывки проводников, и разбитый голем поднимается на ноги. Восстановленный конструкт присоединяется к отряду.","f":"Пробуждённый голем не узнаёт спасителей и поднимает каменные кулаки. Начинается стычка.","v":{"rs":"Ядро вновь светится, но восстановленного конструкта невозможно включить в состав. Вы получаете золото за освобождённые детали."}},"E064.1":{"s":"После нескольких попыток руны вспыхивают в верном порядке, и мост поднимается. У его основания вы находите оставленные припасы.","f":"Неверная последовательность гасит руны, и мост остаётся внизу. На бесплодное ожидание уходит часть припасов."},"E064.2":{"s":"{{heroName}} распознаёт связку древних знаков и активирует подъём моста. На другом берегу удаётся пополнить припасы.","f":"{{heroName}} не может разобрать стёртый символ, поэтому механизм не отвечает. Отряд остаётся без находки."},"E064.3":{"s":"{{heroName}} упирается в заклинившую балку и поднимает пролёт вручную. Отряд проходит по мосту, не задев древние руны.","f":"Балка срывается с опоры, придавливая {{affectedHeroName}}. Переправа заканчивается тяжёлым ранением.","v":{"nf":"Балка падает, но среди доступных бойцов никто не получает тяжёлого ранения. Мост остаётся неподнятым."}},"E064.4":{"s":"Вы разбиваете подъемный механизм и забираете найденные в нём ценные металлические детали. Они приносят отряду золото.","f":"Разрушение запускает защитные руны, и из опор моста выходят вооружённые конструкты. Начинается стычка."},"E065.1":{"s":"Вы снимаете с ленты отчеканенные монеты прежде, чем механическая рука успевает их убрать. Золото отправляется в казну.","f":"Мастерская замечает пропажу готовых деталей и выпускает сторожевые механизмы. Начинается стычка."},"E065.2":{"s":"Вы переключаете станки на производство сухих дорожных пайков. Вместо деталей на ленте появляются припасы.","f":"Станки зажёвывают поданные материалы и останавливаются. Попытка перенастройки обходится в часть припасов."},"E065.3":{"s":"{{heroName}} выравнивает шестерни и меняет порядок операций на панели управления. Мастерская выдаёт золото и припасы.","f":"{{heroName}} находит сломанную зубчатую передачу, которую нечем заменить. Производство остаётся прежним."},"E065.4":{"s":"Вы останавливаете станки и снимаете с панели несколько ценных монетных пластин. Мастерская наконец затихает."},"E066.1":{"s":"Вы освобождаете светящееся ядро и помещаете его в пригодный корпус. Маленький конструкт принимает новое назначение и вступает в отряд.","f":"Попытка переноса ядра заканчивается поломкой крепления и расходами на ремонт. Вы теряете золото, а конструкт остаётся у руин.","v":{"rs":"Ядро удаётся спасти, но новый конструкт не может войти в состав отряда. Вы получаете золото за оставшиеся рабочие детали."}},"E066.2":{"s":"Вы отдаёте разумное ядро скупщику артефактов. Вместо обещанного ему нового назначения в вашу казну поступает золото."},"E066.3":{"s":"{{heroName}} восстанавливает цепочку памяти, и ядро само выбирает служить отряду. Из разобранного корпуса удаётся также забрать припасы.","f":"{{heroName}} не может восстановить повреждённые записи, и ядро снова замолкает. Отряд уходит без помощника.","v":{"rs":"{{heroName}} возвращает ядру память, но разместить нового союзника негде. Полезные детали и найденные припасы остаются у отряда."}},"E066.4":{"s":"Вы не трогаете ядро и оставляете маленький конструкт среди обломков. Его индикатор провожает отряд до поворота."},"E067.1":{"s":"Олень приводит отряд к поляне, где можно собрать съедобные коренья и ягоды. Припасы пополняются, а зверь исчезает между деревьями.","f":"Олень уводит вас в сторону от дороги, а затем скрывается в чащобе. На обратный путь расходуются припасы."},"E067.2":{"s":"Вы подбираетесь к белому оленю и снимаете с рогов золотые цепочки. Их стоимость пополняет казну.","f":"Олень резко опускает рога, защищая себя, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Белый олень отбивает попытку приблизиться, но среди доступных бойцов нет тяжелораненого. Цепочки остаются на рогах."}},"E067.3":{"s":"{{heroName}} держит дистанцию и читает следы, не тревожа оленя. Тропа выводит к припасам и оставленному золоту.","f":"{{heroName}} теряет след среди корней и старых копытных отпечатков. Белый олень исчезает, не оставив добычи."},"E067.4":{"s":"Вы пропускаете белого оленя и не трогаете золотых цепочек. Зверь неспешно уходит по дороге, не обернувшись."},"E068.1":{"s":"Вы тихо вытаскиваете ближайшие мешки из-под сломанной телеги. Медведь не просыпается, а припасы достаются отряду.","f":"Один из мешков задевает камень, и зверь просыпается от стука. Начинается стычка у входа в берлогу."},"E068.2":{"s":"Вы пробираетесь глубже в пещеру и находите уцелевшую кассу обоза вместе с провизией. Добыча пополняет и золото, и припасы.","f":"Тяжёлое дыхание внезапно раздаётся прямо за спиной, а проход из пещеры уже закрыт. Начинается битва."},"E068.3":{"s":"{{heroName}} прижимает зверя щитом к стене ровно настолько, чтобы остальные вынесли мешки. Отряд уносит припасы.","f":"Медведь сминает щит и сбивает {{affectedHeroName}} на камни. Боец получает тяжёлое ранение.","v":{"nf":"Зверь опрокидывает щит, но среди доступных бойцов никто не получает тяжёлого ранения. Мешки остаются у берлоги."}},"E068.4":{"s":"Вы разворачиваете отряд до того, как потревожить пещеру. Разграбленный обоз остаётся лежать у входа."},"E069.1":{"s":"Ворон ведёт отряд от камня к камню до старого тайника. Под корнями находят золото.","f":"Птица исчезает за дальним холмом, оставив вас в стороне от дороги. На поиски обратного пути уходят припасы."},"E069.2":{"s":"Вы поднимаете кольцо и не следуете за птицей. Продажа находки приносит немного золота."},"E069.3":{"s":"{{heroName}} узнаёт знак на кольце и понимает, куда ведёт ворон. У забытого схрона удаётся взять золото и припасы.","f":"{{heroName}} не распознаёт потёртую вязь, и ворон улетает, не дождавшись ответа. Другой награды нет."},"E069.4":{"s":"Вы вспугиваете ворона взмахом плаща. Птица уносится в лес, а кольцо остаётся лежать на дороге."},"E070.1":{"s":"Вы бросаете на обочину часть провизии, и волки переключаются на еду. Отряд уходит, не обнажая оружия."},"E070.2":{"s":"Вы сохраняете строй и не меняете шага, пока вожак не прекращает преследование. Волки постепенно отстают.","f":"Вожак выбирает момент, когда задние ряды растянулись, и стая бросается на отряд. Начинается стычка."},"E070.3":{"s":"{{heroName}} отвлекает стаю ложным следом и возвращается с найденной у звериной тропы провизией. Отряд продолжает путь.","f":"Волки обходят обманный манёвр и бросаются на {{affectedHeroName}}. Боец получает тяжёлое ранение.","v":{"nf":"Стая срывает отвлекающий манёвр, но среди доступных бойцов никто не получает тяжёлого ранения. Отряду приходится отступить без добычи."}},"E070.4":{"s":"Вы строитесь для атаки до того, как волки успевают окружить отряд. Начинается стычка с опасной стаей."},"E071.1":{"s":"Вы успеваете взобраться на скалу, перебрать блестящую добычу и спуститься до возвращения птиц. Золото пополняет казну.","f":"Взрослые птицы возвращаются, когда отряд ещё на скале. {{affectedHeroName}} погибает под их ударами.","v":{"nf":"Птицы возвращаются и вынуждают отряд отступить, но среди доступных бойцов никто не погибает. Добыча остаётся в гнезде."}},"E071.2":{"s":"Вы забираете из гнезда одну драгоценную вещь и успеваете отойти до появления хозяев. Находка приносит золото.","f":"Первая же пропажа привлекает гигантских птиц к скале. Они бросаются на отряд — начинается стычка."},"E071.3":{"s":"{{heroName}} поднимается по выступам, хватает самый ценный предмет и возвращается прежде, чем птицы заметят кражу. Золото оказывается у отряда.","f":"{{heroName}} не успевает сойти с уступа до возвращения птиц, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Птицы срывают быстрый налёт, но среди доступных бойцов никто не получает тяжёлой раны. В гнезде ничего не удаётся взять."}},"E071.4":{"s":"Вы не тревожите гнездо и продолжаете путь вдоль скалы. Над головой раздаётся первый далёкий крик вернувшейся птицы."},"E072.1":{"s":"Вы откапываете сундук из-под корней и находите в нём золотые монеты. Лиса наблюдает из кустов, не приближаясь.","f":"Лопата ломается о камни, а сундук оказывается пустым. На бесполезные поиски уходят деньги за новые инструменты."},"E072.2":{"s":"Под верхним ящиком открывается второй тайник с куда более дорогой добычей. Золото пополняет казну.","f":"Корни обрушиваются в раскоп, и {{affectedHeroName}} получает тяжёлое ранение. До нижнего тайника добраться не удаётся.","v":{"nf":"Глубокий раскоп осыпается, но среди доступных бойцов нет тяжелораненых. Нижний тайник остаётся закрытым."}},"E072.3":{"s":"{{heroName}} пролезает между корнями и вытаскивает сундук, не подрывая землю вокруг. Внутри оказывается золото.","f":"{{heroName}} нащупывает пустой ящик под корнями и выбирается обратно. Подозрительная лиса исчезает в зарослях."},"E072.4":{"s":"Вы оставляете сундук под корнями и не следуете за лисой. Из кустов мелькает рыжий хвост — и пропадает."},"E073.1":{"s":"Вы переступаете круг грибов, и феи отодвигают мешочек прямо к вашим ногам. Монеты достаются отряду.","f":"Круг замыкается за спиной, заставляя вас до утра искать выход с поляны. Поиски обходятся в припасы."},"E073.2":{"s":"Вы выдерживаете сумасшедший танец и получаете от фей свёртки с едой. Веселье кончается прежде, чем у кого-то закружится голова.","f":"Фейский танец ускоряется, пока {{affectedHeroName}} не падает среди светящихся грибов с тяжёлым ранением.","v":{"nf":"Феи закручивают танец до опасной скорости, но среди доступных бойцов никто не получает тяжёлого ранения. Подарков от фей нет."}},"E073.3":{"s":"{{heroName}} повторяет древнее приветствие, и феи прекращают кружить вокруг мешочка. В благодарность они дают золото и припасы.","f":"{{heroName}} не может вспомнить последнее движение обряда. Феи смеются и прячут подарки."},"E073.4":{"s":"Вы обходите грибное кольцо стороной. За спиной слышен смех фей, которым придётся искать других участников игры."},"E074.1":{"s":"Вы оставляете феям часть провизии как знак мирных намерений. Страж отступает и возвращает вам небольшую монетную благодарность."},"E074.2":{"s":"Вы проходите вдоль края тропы, не касаясь бронированного стража. Феи провожают вас сердитыми возгласами.","f":"Гигантская божья коровка перекрывает проход панцирем, и феи поднимают тревогу. Начинается стычка."},"E074.3":{"s":"{{heroName}} удерживает щит перед стражем и не наносит ответного удара. Феи признают намерения мирными и дают припасы.","f":"Страж обрушивает бронированный панцирь на щит, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Страж опрокидывает щит, но среди доступных бойцов никто не получает тяжёлого ранения. Феи не верят вашим намерениям."}},"E074.4":{"s":"Вы пробиваете защиту бронированного стража и забираете золотые украшения с его поста. Добыча достаётся отряду.","f":"Панцирь выдерживает нападение, а феи зовут на помощь всех соседних стражей. Начинается битва."},"E075.1":{"s":"Бабочка уводит отряд через короткий проход между деревьями прямо к забытому складу. Внутри сохранились припасы.","f":"Фея меняет направление слишком часто, и вы теряете её среди одинаковых тропинок. На обратную дорогу уходят припасы."},"E075.2":{"s":"Получив золото, фея рисует подробный маршрут на коре дерева. Вы находите склад и пополняете припасы без новых блужданий."},"E075.3":{"s":"{{heroName}} выбирает наземную тропу параллельно полёту бабочки и выходит к складу раньше проводницы. Отряд забирает припасы.","f":"{{heroName}} теряет бабочку за густыми кронами и не находит нужного поворота. Пустой путь не приносит добычи."},"E075.4":{"s":"Вы благодарите фею за предложение, но остаётесь на знакомой дороге. Бабочка вскоре скрывается над лесом."},"E076.1":{"s":"Оракул принимает плату и переставляет семена в форме дорожной развилки. По её указанию отряд находит припасы."},"E076.2":{"s":"Рисунок из семян приводит вас к спрятанному кошельку. Вы получаете золото, хотя ставку уже отдали оракулу.","f":"Семена складываются в пустой круг, и обещанная удача не приходит. Поставленное золото остаётся у феи."},"E076.3":{"s":"{{heroName}} замечает повторяющийся знак в дорожках семян и верно толкует предсказание. Отряд находит золото и припасы.","f":"{{heroName}} читает рисунок иначе, чем оракул, и подсказка теряет смысл. Никакой находки нет."},"E076.4":{"s":"Вы не платите за предсказание и идёте дальше. Оракул молча стирает дорожки из семян."},"E077.1":{"s":"К рассвету посаженные семена дают крупные съедобные плоды. Отряд заготавливает припасы в дорогу.","f":"Вместо плодов из земли вырастают цепкие хищные лозы. Они бросаются к ногам путников — начинается стычка."},"E077.2":{"s":"Вы засаживаете всю грядку, и к утру фейский сад ломится от съедобных плодов. Припасов хватает на несколько переходов.","f":"Слишком густая посадка оживает сплошной стеной хищных стеблей. Отряду приходится вступить в битву."},"E077.3":{"s":"{{heroName}} отделяет безвредные семена от хищных ещё до посадки. Утром вы собираете богатый урожай припасов.","f":"{{heroName}} не находит надёжного признака безопасности, и посев откладывается. Урожая отряд не получает."},"E077.4":{"s":"Вы отдаёте волшебные семена торговцу, не испытывая их на себе. Он платит золотом за неизвестный будущий урожай."},"E078.1":{"s":"Король принимает венок из рук фейской правительницы и произносит клятву. В ответ она вручает отряду золото и припасы.","f":"Венок затягивается на голове Короля, и древняя клятва обжигает его тяжёлым ранением. Фейская правительница не предлагает награды.","v":{"nf":"Венок вспыхивает, но у Короля не фиксируется тяжёлое ранение. Клятва остаётся незавершённой."}},"E078.2":{"s":"Вы просите фейскую правительницу объяснить клятву без загадок, и она соглашается на ясные условия. В знак согласия вы получаете золото.","f":"Фейская королева принимает ваши уточнения за оскорбление и зовёт придворную стражу. Начинается стычка."},"E078.3":{"s":"{{heroName}} отвечает своей клятвой, не отдавая Короля под чужие условия. Фейская королева вручает отряду золото и припасы.","f":"{{heroName}} не может закончить слова прежде, чем круг цветов распадается. Феи не признают встречную клятву."},"E078.4":{"s":"Вы не позволяете Королю надеть цветочный венок. Фейская правительница забирает его и возвращается в круг без возражений."},"E079.1":{"s":"Гоблин дважды пересчитывает монеты и выдаёт обещанные припасы из-под прилавка. Отряд отходит от тележки без обмана."},"E079.2":{"s":"В закрытом ящике оказывается тайник с золотом, которого гоблин явно не ожидал. Покупка приносит больше, чем стоила.","f":"В ящике только пыль, а гоблин требует ещё денег за якобы сломанную печать. Отряд теряет дополнительное золото сверх цены покупки."},"E079.3":{"s":"Пока гоблины спорят о цене шестерёнок, вы уносите мешки с едой за тележкой. Припасы пополняются.","f":"Один из гоблинов замечает пропажу и свистит своим подручным. Начинается стычка."},"E079.4":{"s":"{{heroName}} перебивает гоблинские выкрики одним точным предложением и выторговывает припасы за уже отданное золото.","f":"Гоблины принимают плату за переговоры, но не соглашаются на цену {{heroName}}. Отряд остаётся без припасов."},"E079.5":{"s":"Вы обходите подозрительную тележку, не трогая ни товары, ни кошель. Гоблины ещё долго спорят, кто упустил прибыль."},"E080.1":{"s":"Гоблины забирают плату и показывают, по каким доскам можно идти. Мост скрипит, но отряд благополучно переходит.","f":"Даже после уплаты пошлины одна из досок ломается, и {{affectedHeroName}} получает тяжёлое ранение. Гоблины делают вид, что ничего не обещали.","v":{"nf":"Оплаченный мост проседает, но среди доступных бойцов никто не получает тяжёлого ранения. Гоблины не возвращают пошлину."}},"E080.2":{"s":"{{heroName}} закрепляет провисшую цепь и выравнивает щиты на настиле. Гоблины платят золотом за спасённый мост.","f":"{{heroName}} обнаруживает, что несущие доски прогнили насквозь. Укрепить мост без полной перестройки не удаётся."},"E080.3":{"s":"Вы перепрыгиваете самые ненадёжные участки и добираетесь до другого берега. Гоблины разочарованно пересчитывают несобранную плату.","f":"Прыжки задерживают колонну, и один мешок с провизией падает в реку. Припасов становится меньше."},"E080.4":{"s":"Вы выбираете длинный обход и теряете часть провизии по дороге. Гоблинский мост остаётся позади вместе с его сомнительными гарантиями."},"E081.1":{"s":"Вы срываете крышку бочки и вместо ловушки находите звонкие монеты. Гоблинская надпись явно должна была отпугнуть конкурентов.","f":"Под крышкой срабатывает пружинный механизм, и {{affectedHeroName}} получает тяжёлое ранение. Бочка рассыпается, не отдав сокровища.","v":{"nf":"Ловушка срабатывает, но среди доступных бойцов никто не получает тяжёлого ранения. Монеты остаются внутри сломанной бочки."}},"E081.2":{"s":"Вы откатываете бочку за поворот и вскрываете её вдали от дороги. Внутри обнаруживается золото.","f":"На ухабе бочка лопается, разбрасывая острые железки по обозу. Часть припасов оказывается испорчена."},"E081.3":{"s":"{{heroName}} замечает под обручем скрытый рычаг и обезвреживает ловушку. После этого бочку можно спокойно открыть и забрать золото.","f":"{{heroName}} находит слишком много подозрительных пружин и советует не касаться крышки. Добычи нет."},"E081.4":{"s":"Вы проходите мимо бочки, не испытывая гоблинскую честность. Звон изнутри постепенно стихает за спиной."},"E082.1":{"s":"Ваша тележка неожиданно приходит первой, несмотря на кривые колёса. Гоблины скрепя сердце выдают золото и припасы.","f":"На последнем повороте тележка переворачивается, и {{affectedHeroName}} получает тяжёлое ранение. Толпа уже приветствует нового победителя.","v":{"nf":"Тележка разбивается на повороте, но среди доступных бойцов никто не получает тяжёлого ранения. Приз остаётся у соперников."}},"E082.2":{"s":"{{heroName}} выравнивает тележку на опасном спуске и вырывает победу. Судьи выдают золото и провиант.","f":"Колесо соскальзывает с оси, и {{affectedHeroName}} получает тяжёлое ранение. Гоблины объявляют гонку законченной.","v":{"nf":"Тележка сходит с трассы, но среди доступных бойцов никто не получает тяжёлого ранения. Победа уходит соперникам."}},"E082.3":{"s":"Вы ставите золото на самого уверенного гонщика, и он действительно финиширует первым. Выигрыш поступает в казну.","f":"Фаворит застревает в грязи уже на старте, а ваша ставка остаётся у гоблинских букмекеров. Никакого выигрыша."},"E082.4":{"s":"Вы незаметно ослабляете крепление на чужой тележке, и соперники сходят с трассы. Призовое золото достаётся отряду.","f":"Гоблины замечают саботаж до старта и окружают вас с гаечными ключами наперевес. Начинается стычка."},"E083.1":{"s":"Гоблин-повар наливает рагу в походные котелки и принимает условленную плату. Запас еды у отряда увеличивается."},"E083.2":{"s":"Вы пробуете рагу, и повар, довольный смелостью гостей, даёт ещё порцию в дорогу. Припасов становится больше.","f":"Бесплатная проба оказывается слишком опасной для желудка: {{affectedHeroName}} получает тяжёлое ранение. Повар поспешно прячет котёл.","v":{"nf":"Рагу вызывает переполох, но среди доступных бойцов никто не получает тяжёлого ранения. Бесплатной еды отряд не получает."}},"E083.3":{"s":"{{heroName}} проверяет ингредиенты и отбирает безопасные порции. За уже заплаченное золото повар выдаёт припасы.","f":"{{heroName}} обнаруживает в котле нечто сомнительное и отказывается от покупки. Плата за проверку остаётся у повара."},"E083.4":{"s":"Вы разгоняете гоблинов и забираете оставленные у котла мешки с едой. Припасы пополняются.","f":"Повар поднимает крик, и торговцы хватают разделочные ножи. Начинается стычка."},"E084.1":{"s":"За купленной картой действительно скрывается тайник, о котором продавец не соврал. Вы находите золото.","f":"Карта ведёт к пустой яме, давно отмеченной на десятке других листов. Уплаченных монет гоблин не возвращает."},"E084.2":{"s":"Гоблин пятится, суёт вам карту и высыпает из кошеля золотые монеты, лишь бы его оставили в покое. Карта остаётся дорожной безделицей, зато золото отправляется в казну.","f":"Продавец свистит, и из кустов выбегают его вооружённые подельники. Вместо карты начинается стычка."},"E084.3":{"s":"{{heroName}} замечает, что цены на обороте нанесены поверх старой подсказки, и находит настоящий тайник. Золото пополняет казну.","f":"Продавец объявляет расспросы порчей товара и взыскивает плату. Отряд теряет золото, так и не проверив карту."},"E084.4":{"s":"Вы проходите мимо гоблина с картой, не позволяя ему назвать четвёртую цену. Он тут же переключается на следующих путников."},"E085.1":{"s":"Вы собираете неповреждённые мешки и монеты среди обломков каравана. Отряд пополняет припасы и золото.","f":"Пока вы разбираете груз, из оврага возвращаются налётчики. Начинается стычка."},"E085.2":{"s":"Следы нападавших приводят к спрятанной кассе каравана. Отряд забирает золото, не встретив охраны.","f":"Погоня приводит к укреплённому лагерю налётчиков, который уже заметил ваш отряд. Начинается битва."},"E085.3":{"s":"{{heroName}} осматривает овраг, находит безопасный спуск и указывает на уцелевший груз. Золото и припасы достаются отряду.","f":"На спуске из оврага ударяет оставшийся в засаде налётчик, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Разведка обнаруживает засаду, но среди доступных бойцов никто не получает тяжёлого ранения. Груз остаётся в овраге."}},"E085.4":{"s":"Вы оставляете разбитые повозки на дороге и не идёте за следами в овраг. Отряд сохраняет силы, но не получает добычи."},"E086.1":{"s":"Вы снимаете с безымянного алтаря старые монеты, не касаясь кровавых следов. Золото отправляется в казну.","f":"Стоит сдвинуть монеты, как алтарь выпускает резкий магический удар. {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Алтарь отвечает опасным всплеском, но среди доступных бойцов никто не получает тяжёлого ранения. Монеты остаются на месте."}},"E086.2":{"s":"Вы оставляете золото на алтаре, и рядом открывается тайник с дорожной едой. Отряд забирает припасы.","f":"Монеты исчезают с камня, но никакого ответа не следует. Отряд лишается подношения без награды."},"E086.3":{"s":"{{heroName}} распознаёт в резьбе старую систему тайников и открывает нишу с золотом. Сам алтарь остаётся нетронутым.","f":"Во время исследования из-за алтаря выходят вооружённые хранители, не желающие объяснений. Начинается стычка."},"E086.4":{"s":"Вы разбиваете каменный алтарь и находите в основании спрятанные монеты. Золото достаётся отряду.","f":"Трещина в алтаре выпускает зов, на который отвечают вооружённые приверженцы неизвестной силы. Начинается битва."},"E087.1":{"s":"Вы выбираете одного из наёмников, передаёте плату и заключаете контракт у общего костра. Новый боец вступает в отряд.","v":{"rs":"Кандидат согласен служить, но свободного места для нового бойца не находится. Вместо найма отряд получает золото."}},"E087.2":{"s":"Один из наёмников соглашается ждать доли будущей добычи вместо немедленной платы. Он вступает в отряд.","f":"Кандидат отвергает обещание доли и требует компенсацию за потраченное время. Отряд теряет золото без нового бойца.","v":{"rs":"Наёмник принимает предложение о доле, но войти в состав не может. Вместо контракта вы получаете золото."}},"E087.3":{"s":"{{heroName}} устраивает торг между кандидатами и добивается согласия за уже внесённую плату. Один наёмник присоединяется к отряду.","f":"Кандидаты не могут договориться о цене даже при посредничестве {{heroName}}. Уплаченные за торг деньги не возвращаются.","v":{"rs":"{{heroName}} добивается соглашения, но свободного места для новобранца нет. Вместо пополнения отряду достаётся золото."}},"E087.4":{"s":"Кости удачно ложатся на стол, и наёмники отдают вам выигрыш. Поставленное золото уже ушло в общий котёл.","f":"В последнем броске соперник выбрасывает более сильную комбинацию. Ваша ставка остаётся у наёмников."},"E087.5":{"s":"Вы не выбираете нового бойца и оставляете наёмников у костра. Их спор о следующем контракте слышен ещё долго."},"E088.1":{"s":"Каменная дверь с символом пешки открывает кладовую с дорожными припасами. Вы забираете их и возвращаетесь к проходу.","f":"Дверь с пешкой ведёт в заваленный коридор, где приходится потратить часть припасов, прежде чем выбраться."},"E088.2":{"s":"За дверью с конём скрыт сундук с золотом, оставленный прежними хозяевами скалы.","f":"Из прохода с конём выходят вооружённые стражи и блокируют обратный путь. Начинается стычка."},"E088.3":{"s":"Дверь со слоном открывается в нишу с золотом. Вы успеваете забрать находку до закрытия каменной плиты.","f":"Скрытая плита ударяет при открытии двери, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Дверь захлопывается с опасным ударом, но среди доступных бойцов никто не получает тяжёлого ранения. Золото остаётся внутри."}},"E088.4":{"s":"{{heroName}} поднимает тяжёлую створку с ладьёй и обнаруживает сундук с золотом за ней.","f":"Вес каменной двери оказывается слишком велик, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Створка срывается с опоры, но среди доступных бойцов никто не получает тяжёлого ранения. Дверь остаётся закрытой."}},"E088.5":{"s":"Вы не выбираете ни одной из пяти дверей. Каменные знаки остаются ждать следующего путника."},"E089.1":{"s":"Вы быстро собираете уцелевшие монеты, пока горячие не успевают обжечь руки. Казна пополняется золотом.","f":"Среди падающих монет оказывается раскалённый слиток, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Раскалённый металл заставляет отряд отступить, но среди доступных бойцов никто не получает тяжёлого ранения. Добычи нет."}},"E089.2":{"s":"Вы выбираете только монеты, от которых не идёт пар, и складываете их в мешок. Золото достаётся отряду.","f":"Холодные монеты оказываются хрупкими и рассыпаются в пыль, едва вы пытаетесь их поднять. Ничего ценного не остаётся."},"E089.3":{"s":"{{heroName}} находит безопасные промежутки между падающими раскалёнными монетами. Отряд успевает собрать золото.","f":"{{heroName}} вынужден остановиться перед сплошным потоком горячего металла. Добыча остаётся лежать на дороге."},"E089.4":{"s":"Вы сворачиваете с дороги и обходите место, где с неба падает металл. Странные монеты остаются чужой находкой."},"E090.1":{"s":"Хозяин туманной гостиницы принимает плату, выделяет комнаты и собирает припасы в дорогу. Отряд покидает двор на рассвете."},"E090.2":{"s":"Вы выигрываете карточную партию у посетителей гостиницы и забираете золото со стола. Ставка уже оплачена.","f":"За карточным столом вам не везёт: последний козырь оказывается у соперника. Поставленное золото потеряно."},"E090.3":{"s":"Молчаливый демон наконец отвечает на ваш вопрос и указывает тайник с золотом. Отряд забирает находку.","f":"Демон отодвигает стул и без слов подаёт знак охране постоялого двора. Начинается стычка."},"E090.4":{"s":"{{heroName}} собирает рассказы гостей и по ним находит небольшой запас дорожной еды. Припасы пополняются.","f":"{{heroName}} слышит пять разных версий одной истории и не может отделить правду от вымысла. Отряд уходит без полезных сведений."},"E090.5":{"s":"Вы не входите в незнакомый постоялый двор. Через несколько поворотов огни гостиницы исчезают за туманом."},"E091.1":{"s":"Вы занимаете пустую сигнальную башню до прибытия незнакомых воинов. В сторожевой нише находится золото, оставленное прежним гарнизоном.","f":"Вооружённые силуэты добираются до башни раньше вас и перекрывают лестницу. Начинается стычка."},"E091.2":{"s":"Вы успеваете оборудовать оборонительную позицию и находите в башне немного провизии. Но вооружённые отряды уже подходят — начинается битва.","f":"Колокол продолжает звать воинов, пока отряд безуспешно укрепляет башню. Битва начинается прежде, чем оборона готова."},"E091.3":{"s":"{{heroName}} закрепляет ворота башни и обнаруживает под старым настилом золото. До прибытия вооружённых силуэтов отряд успевает уйти.","f":"{{heroName}} не успевает закрыть все подходы, и воины вступают на нижний ярус. Начинается битва."},"E091.4":{"s":"Вы отходите от башни до появления войск. Самозвонящий колокол ещё долго слышен за холмами."},"E092.1":{"s":"Вы пересекаете поток красного песка и добираетесь до сундуков на дальнем берегу. Один из них наполнен золотом.","f":"Подвижный песок проваливается под ногами, и {{affectedHeroName}} получает тяжёлое ранение. До сундуков не добраться.","v":{"nf":"Красный песок увлекает отряд назад к берегу, но среди доступных бойцов никто не получает тяжёлого ранения. Сундуки остаются недоступны."}},"E092.2":{"s":"Вы расходуете припасы на подготовку переправы и закрепляете страховочные верёвки. За потоком песка удаётся забрать золото.","f":"Подготовка не помогает: опоры уходят в красный песок, и путь к сундукам закрывается. Потраченные припасы не вернуть."},"E092.3":{"s":"{{heroName}} собирает устойчивый настил над движущимся песком. На другом берегу отряд находит золото и уцелевшую провизию.","f":"{{heroName}} обнаруживает, что берег слишком рыхлый для опор. Построить переправу не удаётся."},"E092.4":{"s":"Вы идёте вверх по руслу в поисках сухой отмели. Обход находится, но на лишний переход уходят припасы."},"E093.1":{"s":"Вы спускаетесь в старый колодец и обнаруживаете человека, который не смог выбраться сам. Спасённый соглашается вступить в отряд.","f":"На дне вместо пленника вас встречают вооружённые обитатели подземелья. Начинается стычка.","v":{"rs":"Вы вытаскиваете узника из колодца, но принять его в отряд не удаётся. В благодарность спасённый отдаёт золото."}},"E093.2":{"s":"На вашу верёвку отвечает сильный рывок, и вскоре из колодца выбирается измученный путник. Он решает идти с отрядом.","f":"Верёвку вытаскивают пустой, а голос больше не отзывается. На долгую попытку спасения уходят припасы.","v":{"rs":"Путник выбирается по верёвке, но свободного места для него нет. Он оставляет спасителям золото."}},"E093.3":{"s":"{{heroName}} спускается первым, находит пленника и выводит его вместе со старым кошельком. Спасённый присоединяется к отряду, золото пополняет казну.","f":"Во тьме колодца на {{affectedHeroName}} обрушивается скрытый удар, причиняя тяжёлое ранение. Спасение срывается.","v":{"rs":"{{heroName}} выводит пленника и находит его кошелёк, но новый боец не может присоединиться к отряду. Золото всё равно достаётся спасителям.","nf":"Разведка колодца срывается, но среди доступных бойцов никто не получает тяжёлого ранения. Зовущий остаётся внизу."}},"E093.4":{"s":"Вы сбрасываете в колодец камни и закрываете горловину обломками. Голос больше не слышен, и отряд продолжает путь."},"E094.1":{"s":"Вы раскладываете золотые монеты в углублениях пальцев статуи. Под ладонью открывается ниша с припасами.","f":"Статуя принимает подношение, но ладонь не двигается. Припасов не находится, золото остаётся в каменных выемках."},"E094.2":{"s":"После щедрого подношения ладонь статуи опускается и открывает большую кладовую. Отряд забирает припасы.","f":"Статуя выдаёт лишь крошечный свёрток провизии, хотя золота вы оставили много. Большая кладовая остаётся закрытой."},"E094.3":{"s":"Вы вытаскиваете старые монеты из углублений каменной ладони прежде, чем она успевает сомкнуться. Добыча пополняет казну.","f":"Ладонь поворачивается, и из основания статуи выходят вооружённые хранители. Начинается стычка."},"E094.4":{"s":"{{heroName}} читает посвящение на постаменте и находит скрытую створку у ног статуи. За ней лежат золото и припасы.","f":"{{heroName}} различает лишь обрывки посвящения, которых недостаточно для открытия тайника. Отряд уходит ни с чем."},"E094.5":{"s":"Вы проходите мимо раскрытой каменной ладони, ничего не оставляя и не забирая. Статуя остаётся неподвижной."},"E095.1":{"s":"Первый лагерь принимает вашу поддержку и выплачивает оговорённое золото за оказанную помощь. Отряд покидает поле до столкновения армий.","f":"Соседи первого лагеря считают вас частью его сил и выступают навстречу. Начинается стычка."},"E095.2":{"s":"Командиры второго лагеря соглашаются заплатить за вашу поддержку и отдают золото. Пока остальные спорят, отряд успевает уйти.","f":"Выбор второго знамени втягивает вас в столкновение двух других лагерей. Начинается битва."},"E095.3":{"s":"Третий лагерь платит больше всех за решительное согласие. Золото переходит в казну ещё до начала чужого сражения.","f":"Первые два лагеря объединяются против нового союзника своего соперника. Начинается битва."},"E095.4":{"s":"{{heroName}} усаживает трёх командиров за один стол и добивается перемирия. За посредничество отряд получает золото и припасы.","f":"Один из командиров срывает переговоры и выводит своих бойцов к вашему отряду. Начинается стычка."},"E095.5":{"s":"Вы не принимаете ничьё знамя и проходите между лагерями до наступления темноты. Спор трёх командиров остаётся позади."},"E096.1":{"s":"Король садится на пустующий трон, и из подлокотников выдвигается ларец с золотом. Отряд забирает находку.","f":"Спинка трона сжимается вокруг Короля, оставляя тяжёлое ранение. Древний механизм отпускает его лишь после долгой борьбы.","v":{"nf":"Трон пытается сковать Короля, но тяжёлое ранение не фиксируется. Ларец остаётся закрытым."}},"E096.2":{"s":"Король надевает корону без герба, и у основания трона открывается хранилище. Отряд забирает золото и припасы.","f":"Корона срастается с висками Короля и отнимает у него жизнь. С гибелью Короля путешествие заканчивается.","v":{"nf":"Корона не принимает Короля, и смертельный исход не наступает. Сокровища трона остаются недоступны."}},"E096.3":{"s":"{{heroName}} находит на нижней кромке трона скрытый шов и извлекает ларец с золотом, не касаясь короны.","f":"Когда {{heroName}} исследует резьбу, трон выбрасывает острый осколок. {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Трон отвечает острым выбросом, но среди доступных бойцов никто не получает тяжёлого ранения. Ларец остаётся спрятанным."}},"E096.4":{"s":"Вы разбиваете корону на сиденье и находите внутри золотую оправу. Её стоимость пополняет казну.","f":"Корона не поддаётся ударам, а её поверхность затягивает трещины. Добычи отряд не получает."},"E096.5":{"s":"Вы оставляете и корону, и пустующий трон нетронутыми. На дороге вскоре не остаётся даже их следа."},"E097.1":{"s":"Вы кладёте монеты на прилавок, который виден только краем глаза. Вместо них появляется свёрток с припасами.","f":"Невидимый торговец забирает плату, а затем требует ещё столько же за несуществующую доставку. Отряд теряет дополнительное золото и остаётся без припасов."},"E097.2":{"s":"Вы оставляете плату и просите прислать спутника; из пустоты выходит наёмник, согласный служить отряду.","f":"Монеты исчезают, но вместо спутника голос рынка требует доплату за отмену заказа. Вы теряете ещё золото, никого не наняв.","v":{"rs":"Невидимый рынок принимает заказ, но привести нового бойца не удаётся. Вместо спутника он возвращает часть стоимости золотом."}},"E097.3":{"s":"{{heroName}} нащупывает границу чар и обнаруживает, где торговцы прячут настоящие кошели. Отряд получает золото.","f":"{{heroName}} видит лишь отражения прилавков, которые исчезают при попытке подойти. Никакой находки нет."},"E097.4":{"s":"Вы перехватываете невидимый кошель прежде, чем он исчезает под прилавком. В нём оказывается золото.","f":"За невидимой стойкой звенит тревожный колокольчик, и вооружённые хранители рынка преграждают путь. Начинается стычка."},"E097.5":{"s":"Вы не оставляете монет там, где не видно торговца. Голоса рынка затихают после нескольких шагов."},"E098.1":{"s":"Вы цепляетесь за выступы каменной кладки и добираетесь до освещённого окна. В верхнем помещении находится золото.","f":"Один из выступов обрывается, и {{affectedHeroName}} получает тяжёлое ранение при падении. Свет наверху не гаснет.","v":{"nf":"Выступ ломается, но среди доступных бойцов никто не получает тяжёлого ранения. Внутрь башни попасть не удаётся."}},"E098.2":{"s":"{{heroName}} замечает непрочную плиту у основания башни и открывает проход к кладовой с золотом.","f":"Кладка обрушивается раньше, чем {{heroName}} успевает укрепить её, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Слабая кладка осыпается, но среди доступных бойцов никто не получает тяжёлого ранения. Проход остаётся закрытым."}},"E098.3":{"s":"{{heroName}} находит в тени стены невидимую дверную арку и открывает её магическим знаком. В башне удаётся взять золото и припасы.","f":"{{heroName}} обходит башню несколько раз, но магический вход так и не проявляется. Отряд не получает добычи."},"E098.4":{"s":"Вы разбиваете часть стены всем отрядом и добираетесь до сундука с золотом. Башня остаётся с зияющим проломом.","f":"Удары пробуждают стражей башни, которые выходят из пролома с оружием. Начинается битва."},"E098.5":{"s":"Вы оставляете башню без двери стоять посреди пустой равнины. Свет на её вершине продолжает гореть."},"E099.1":{"s":"Вы осторожно собираете запечатанные мешки у костра. В них находятся пригодные к дороге припасы.","f":"Только вы поднимаете последний мешок, как из темноты выходят вооружённые преследователи пропавшего отряда. Начинается стычка."},"E099.2":{"s":"В сложенном снаряжении обнаруживается дорожная казна. Золото переходит к вашему отряду.","f":"Когда вы тянетесь к кошелю, спрятанная в плаще ловушка срабатывает, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Ловушка в снаряжении срабатывает, но среди доступных бойцов никто не получает тяжёлого ранения. Золото остаётся у костра."}},"E099.3":{"s":"{{heroName}} замечает следы волочения за костром и находит спрятанные в стороне припасы и золото.","f":"{{heroName}} находит признаки засады, но вооружённые преследователи уже рядом. Начинается стычка."},"E099.4":{"s":"Вы затаиваетесь у оставленного костра и перехватываете кошель вернувшегося грабителя. Золото достаётся отряду.","f":"На огонь приходят не одиночки, а целый вооружённый отряд. Ваша засада превращается в битву."},"E099.5":{"s":"Вы не разбираете чужое снаряжение и не пытаетесь выяснить судьбу пропавших. Костёр остаётся гореть позади."},"E100.1":{"s":"Вы оставляете на светящихся камнях золото, и тропа успокаивается. В награду дорога открывает тайник с припасами."},"E100.2":{"s":"Вы отдаёте дороге часть продовольствия, и между камнями появляется старый золотой кошель. Отряд забирает плату за сделку."},"E100.3":{"s":"Вы позволяете дороге выбрать одного из бойцов, но свет гаснет, не причинив вреда. Вместо крови камни открывают золото.","f":"Камни вспыхивают под ногами {{affectedHeroName}}, оставляя тяжёлое ранение. Обещанного золота нет.","v":{"nf":"Светящиеся камни требуют жертву, но среди доступных бойцов никто не получает тяжёлого ранения. Золото не появляется."}},"E100.4":{"s":"Король принимает вызов дороги, и свет расступается перед его шагами. Камни открывают золото и припасы.","f":"Камни отвечают на вызов смертельным ударом, и Король погибает. Его путешествие заканчивается здесь.","v":{"nf":"Дорога отвергает вызов, но Король остаётся жив. Золото и припасы не появляются."}},"E100.5":{"s":"Вы отвергаете любую плату, и дорога поднимает против отряда своих вооружённых защитников. Начинается битва."}});
export { OUTCOMES_E051_E100 };
